div.script:
(function () {
    var countrySelect = document.getElementById('lm_zone_country');
    var stateSelect = document.getElementById('lm_zone_state');
    if (!countrySelect || !stateSelect) return;
    function text(id, fallback) {
        var el = document.getElementById(id);
        return el ? el.textContent.trim() : fallback;
    }
    var allOptions = Array.prototype.slice.call(stateSelect.querySelectorAll('option[data-country_id]'));
    countrySelect.addEventListener('change', function () {
        var countryId = countrySelect.value;
        stateSelect.innerHTML = '';
        if (!countryId) {
            var placeholder = document.createElement('option');
            placeholder.value = '';
            placeholder.textContent = text('lm_zone_txt_first', 'select a country first...');
            stateSelect.appendChild(placeholder);
            stateSelect.disabled = true;
            return;
        }
        var matching = allOptions.filter(function (opt) {
            return opt.getAttribute('data-country_id') === countryId;
        });
        if (!matching.length) {
            var none = document.createElement('option');
            none.value = '';
            none.textContent = text('lm_zone_txt_none', 'no states for this country');
            stateSelect.appendChild(none);
            stateSelect.disabled = true;
            return;
        }
        var blank = document.createElement('option');
        blank.value = '';
        blank.textContent = text('lm_zone_txt_select', 'select...');
        stateSelect.appendChild(blank);
        matching.forEach(function (opt) {
            var clone = opt.cloneNode(true);
            clone.classList.remove('d-none');
            stateSelect.appendChild(clone);
        });
        stateSelect.disabled = false;
    });
})();
